import fs from "node:fs";

const edits = [
  ["package.json", '"version": "1.22.0"', '"version": "1.23.0"'],
  ["src-tauri/tauri.conf.json", '"version": "1.22.0"', '"version": "1.23.0"'],
  ["src-tauri/Cargo.toml", 'version = "1.22.0"', 'version = "1.23.0"'],
];

for (const [file, from, to] of edits) {
  const text = fs.readFileSync(file, "utf8");
  if (!text.includes(from)) throw new Error(`missing ${from} in ${file}`);
  fs.writeFileSync(file, text.replace(from, to));
}

// versionCode = 10000 + minor * 100 + patch -> 1.23.0 -> 12300.
// This file is generated by `tauri android init` and is not tracked by git,
// so it has to be patched by hand on every release.
const propsFile = "src-tauri/gen/android/app/tauri.properties";
if (fs.existsSync(propsFile)) {
  const props = fs
    .readFileSync(propsFile, "utf8")
    .replace("tauri.android.versionName=1.22.0", "tauri.android.versionName=1.23.0")
    .replace("tauri.android.versionCode=12200", "tauri.android.versionCode=12300");
  fs.writeFileSync(propsFile, props);
  console.log("bumped tauri.properties too");
}
console.log("bumped to 1.23.0 (versionCode 12300)");
